  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload.get('nodes')
    if not nodes:
        raise ValueError('Missing or empty nodes list')
    required_symbols = set(payload.get('required_symbols', []))
    if not required_symbols:
        raise ValueError('required_symbols must be non-empty')
    node_map = {}
    for n in nodes:
        for key in ('id', 'parent', 'symbol', 'depth', 'removable', 'utility'):
            if key not in n:
                raise ValueError(f'Node missing field {key}')
        nid = n['id']
        if nid in node_map:
            raise ValueError(f'Duplicate node id {nid}')
        node_map[nid] = n
    # Find root
    root_id = None
    for n in nodes:
        if n['depth'] == 0 and n['parent'] is None:
            if root_id is not None:
                raise ValueError('Multiple root nodes')
            root_id = n['id']
    if root_id is None:
        raise ValueError('No root node found')
    # Validate parent references
    children = {nid: [] for nid in node_map}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            if pid not in node_map:
                raise ValueError(f'Parent {pid} not found')
            children[pid].append(n['id'])
    # Check required symbols are initially present
    all_symbols = {n['symbol'] for n in nodes}
    missing_required = required_symbols - all_symbols
    if missing_required:
        raise ValueError(f'Required symbols missing from tree: {missing_required}')
    retained = set(node_map.keys())
    removal_order = []
    # Group nodes by depth
    depth_groups = {}
    for n in nodes:
        d = n['depth']
        depth_groups.setdefault(d, []).append(n['id'])
    depths = sorted(depth_groups.keys(), reverse=True)
    changed = True
    while changed:
        changed = False
        for d in depths:
            candidates = sorted(depth_groups[d])
            for nid in candidates:
                if nid not in retained:
                    continue
                node = node_map[nid]
                if not node['removable']:
                    continue
                if node['symbol'] in required_symbols:
                    continue
                if nid == root_id:
                    continue
                # Check retained children
                has_retained_children = any(cid in retained for cid in children[nid])
                if has_retained_children:
                    continue
                # Tentative removal
                retained.remove(nid)
                current_symbols = {node_map[rid]['symbol'] for rid in retained}
                if required_symbols.issubset(current_symbols):
                    removal_order.append(nid)
                    changed = True
                else:
                    retained.add(nid)
    retained_ids = sorted(retained)
    return {'retained_ids': retained_ids, 'removal_order': removal_order}"
}
